"""Q1 驗算：純 Python csv 迴圈 + 依 docs/taiwan-regions.md 手抄的縣市清單（不用 tw.py / pandas）。"""
import csv

REGIONS = {
    "北部": ["臺北市", "新北市", "基隆市", "桃園市", "新竹市", "新竹縣", "宜蘭縣"],
    "中部": ["臺中市", "苗栗縣", "彰化縣", "南投縣", "雲林縣"],
    "南部": ["臺南市", "高雄市", "嘉義市", "嘉義縣", "屏東縣", "澎湖縣"],
    "東部": ["花蓮縣", "臺東縣"],
}
lookup = {c: r for r, cs in REGIONS.items() for c in cs}
tot = {r: 0 for r in REGIONS}
grand = 0
with open("data/contest/county_stats/county_monthly_stats.csv", encoding="cp950", newline="") as f:
    for row in csv.DictReader(f):
        if not row["統計期"].startswith("113/"):
            continue
        v = row["觀光遊憩人次"].replace(",", "").strip()
        if row["縣市別"] == "總計":
            grand += int(v)
            continue
        if v == "-":
            continue
        r = lookup.get(row["縣市別"].replace("台", "臺"))
        if r:
            tot[r] += int(v)
for r, v in tot.items():
    print(r, v)
print("澎湖除外南部", tot["南部"])
print("總計列 113 年合計", grand)

